# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN EHL-İ KİTAP İLE İLİŞKİLERİNİN TEMEL İLKELERİ</text>\n  <rect x="30" y="55" width="200" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İnanç Özgürlüğü</text>\n  <text x="130" y="110" text-anchor="middle" font-size="11.5" fill="#334155">"Dinde zorlama yoktur."</text>\n  <text x="130" y="130" text-anchor="middle" font-size="11" fill="#475569">(Bakara Suresi, 256. ayet)</text>\n  <text x="130" y="160" text-anchor="middle" font-size="11.5" fill="#334155">Kimseye inancından dolayı</text>\n  <text x="130" y="180" text-anchor="middle" font-size="11.5" fill="#334155">baskı yapılmamış, ibadet</text>\n  <text x="130" y="200" text-anchor="middle" font-size="11.5" fill="#334155">yerlerine dokunulmamıştır.</text>\n  <rect x="250" y="55" width="200" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Adalet ve Ahde Vefa</text>\n  <text x="350" y="110" text-anchor="middle" font-size="11.5" fill="#334155">Hukuk önünde din farkı</text>\n  <text x="350" y="130" text-anchor="middle" font-size="11.5" fill="#334155">gözetmeksizin adaletle</text>\n  <text x="350" y="150" text-anchor="middle" font-size="11.5" fill="#334155">hükmedilmiş; yapılan</text>\n  <text x="350" y="170" text-anchor="middle" font-size="11.5" fill="#334155">antlaşmalara (Medine</text>\n  <text x="350" y="190" text-anchor="middle" font-size="11.5" fill="#334155">Sözleşmesi) sadık kalınmıştır.</text>\n  <rect x="470" y="55" width="200" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">İnsani Nezaket</text>\n  <text x="570" y="110" text-anchor="middle" font-size="11.5" fill="#334155">Yahudi cenazesine</text>\n  <text x="570" y="130" text-anchor="middle" font-size="11.5" fill="#334155">"O da bir insan değil mi?"</text>\n  <text x="570" y="150" text-anchor="middle" font-size="11.5" fill="#334155">diyerek ayağa kalkmış,</text>\n  <text x="570" y="170" text-anchor="middle" font-size="11.5" fill="#334155">hastalarını ziyaret edip</text>\n  <text x="570" y="190" text-anchor="middle" font-size="11.5" fill="#334155">komşuluk hukukunu korumuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MEDİNE SÖZLEŞMESİ VE YAHUDİ KABİLELERİYLE İLİŞKİLER</text>\n  <rect x="35" y="55" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Medine Sözleşmesi (622)</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Müslümanlar ile Yahudiler arasında imzalandı.</text>\n  <text x="55" y="132" font-size="11.5" fill="#334155">• Din ve vicdan hürriyeti güvenceye alındı.</text>\n  <text x="55" y="156" font-size="11.5" fill="#334155">• Medine dış saldırılara karşı birlikte savunulacaktı.</text>\n  <text x="55" y="180" font-size="11.5" fill="#334155">• Anlaşmazlıklarda hakem Hz. Muhammed (s.a.v.) oldu.</text>\n  <text x="55" y="208" font-size="11" font-weight="bold" fill="#1e40af">Barış içinde birlikte yaşama belgesidir.</text>\n  <rect x="355" y="55" width="310" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="510" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Sözleşmeyi Bozan Kabileler</text>\n  <text x="375" y="110" font-size="11.5" fill="#334155">1. Benî Kaynuka: Bedir\'den sonra taşkınlık</text>\n  <text x="385" y="128" font-size="11" fill="#475569">yapıp sözleşmeyi ilk bozan kabile oldu.</text>\n  <text x="375" y="154" font-size="11.5" fill="#334155">2. Benî Nadir: Uhud sonrasında Peygamberimize</text>\n  <text x="385" y="172" font-size="11" fill="#475569">suikast girişiminde bulununca sürgün edildi.</text>\n  <text x="375" y="198" font-size="11.5" fill="#334155">3. Benî Kurayza: Hendek Savaşı\'nda müşriklerle</text>\n  <text x="385" y="216" font-size="11" fill="#475569">iş birliği yaparak Medine\'yi arkadan vurdu.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN HRİSTİYANLARLA İLİŞKİLERİ</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Habeşistan Kralı Necaşi Ashame</text>\n  <text x="55" y="110" font-size="11.5" fill="#334155">• Mekke döneminde Habeşistan\'a hicret eden</text>\n  <text x="65" y="128" font-size="11" fill="#475569">Müslümanları adaletle koruyan Hristiyan kraldır.</text>\n  <text x="55" y="156" font-size="11.5" fill="#334155">• Müşrik elçilerine muhacirleri teslim etmemiştir.</text>\n  <text x="55" y="184" font-size="11.5" fill="#334155">• Daha sonra İslam\'ı kabul etmiş; vefat ettiğinde</text>\n  <text x="65" y="204" font-size="11" font-weight="bold" fill="#166534">Peygamberimiz gıyabi cenaze namazı kıldırmıştır.</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Necran Hristiyanları Heyeti</text>\n  <text x="380" y="110" font-size="11.5" fill="#334155">• Yemen\'in Necran bölgesinden Medine\'ye gelen</text>\n  <text x="390" y="128" font-size="11" fill="#475569">60 kişilik Hristiyan temsilci heyetidir.</text>\n  <text x="380" y="156" font-size="11.5" fill="#334155">• Peygamberimiz onları Mescid-i Nebevî\'de ağırlamış</text>\n  <text x="390" y="174" font-size="11" fill="#475569">ve mescitte ibadet etmelerine izin vermiştir.</text>\n  <text x="380" y="202" font-size="11.5" font-weight="bold" fill="#854d0e">• Din ve mal güvenliği sağlayan antlaşma yapılmıştır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
